mapper.select:
select p.PROD_ID as prodId,/** 产品代码**/ p.PROD_NAME as prodName,/** 产品名称**/ p.REG_CODE as regCode, /** 理财信息系统登记编码**/ p.IVSTORIENTATION as ivstorientation,/** 投资性质**/ p.CASH_PRIN_CCY as cashPrinCcy,/** 兑付本金币种**/ p.RISK_LEVEL as riskLevel,/** 产品风险等级**/ p.VDATE as vdate,/** 起息日**/ r.DEALDATE as dealdate,/** 报告日期**/ p.IN_DEP_NAME as inDepName,/** 境内托管机构名称**/ p.OUT_DEP_NAME as outDepName, /** 境外托管机构名称**/ p.CUSTOMER_TYPE as customerType,/** 客户类型**/ case when p.IN_DEP_NAME is not null and p.OUT_DEP_NAME is not null then concat_ws('、',p.IN_DEP_NAME,p.OUT_DEP_NAME) when p.IN_DEP_NAME is not null and p.OUT_DEP_NAME is null then p.IN_DEP_NAME when p.IN_DEP_NAME is null and p.OUT_DEP_NAME is not null then p.OUT_DEP_NAME else '' end as depName, /** 境内托管机构名称 + 境外托管机构名称**/ '华夏理财有限责任公司' as managerName /** 产品管理人**/ from CHB_PRD_BASEINFO p inner join ( select distinct t.DEALDATE, t.PROD_ID from CHB_INVEST_TRADE t, CHB_ASSET_INFO a where t.ASSET_CODE = a.ASSET_CODE and a.`STATUS` = 'E' and t.`STATUS` = 'E' and a.ASSET_TYPE2 in ( select SRCFIELD1 from chb_type_mapping_ex where MAPPINGCODE = 'ChbInvestOperation001' ) /** 指定非标资产的类别**/ and t.CUR_ASSET_TYPE in ('01', '02') /** 买入或者卖出/到期**/
and t.DEALDATE >= #{dealdateStart,jdbcType=DATE}
and t.DEALDATE <= #{dealdateEnd,jdbcType=DATE}
) r on r.PROD_ID = p.PROD_ID where p.`STATUS` = 'E'
and p.PROD_ID in
#{prodId,jdbcType=VARCHAR}
